PRAGMA foreign_keys = ON;
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE media(id TEXT PRIMARY KEY,provider TEXT NOT NULL DEFAULT 'google-drive',original_url TEXT NOT NULL,file_id TEXT NOT NULL,display_url TEXT NOT NULL,alt_text TEXT NOT NULL DEFAULT '',caption TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE posts(id TEXT PRIMARY KEY,title TEXT NOT NULL,subtitle TEXT NOT NULL DEFAULT '',slug TEXT NOT NULL UNIQUE,excerpt TEXT NOT NULL DEFAULT '',content_json TEXT NOT NULL,content_html TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','published','scheduled')),category_id TEXT REFERENCES categories(id) ON DELETE SET NULL,cover_image_id TEXT REFERENCES media(id) ON DELETE SET NULL,author TEXT NOT NULL DEFAULT 'Equipe InfoNaVidaReal',featured INTEGER NOT NULL DEFAULT 0,toc INTEGER NOT NULL DEFAULT 1,seo_title TEXT NOT NULL DEFAULT '',seo_description TEXT NOT NULL DEFAULT '',canonical_url TEXT NOT NULL DEFAULT '',social_image TEXT NOT NULL DEFAULT '',published_at TEXT,scheduled_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX posts_public ON posts(status,published_at,scheduled_at);
CREATE INDEX posts_category ON posts(category_id,status,published_at);
CREATE TABLE pages(id TEXT PRIMARY KEY,title TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,content_json TEXT NOT NULL,content_html TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),seo_title TEXT NOT NULL DEFAULT '',seo_description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE revisions(id TEXT PRIMARY KEY,content_type TEXT NOT NULL,content_id TEXT NOT NULL,content_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX revisions_content ON revisions(content_type,content_id,created_at);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE redirects(id TEXT PRIMARY KEY,old_path TEXT NOT NULL UNIQUE,new_path TEXT NOT NULL,created_at TEXT NOT NULL);
